   COMMENT ON COLUMN "TOPO_VERTEX"."NODE_PARENT" IS '节点对应父节点';
   COMMENT ON COLUMN "TOPO_VERTEX"."NODE_X" IS 'x的坐标位置';
   COMMENT ON COLUMN "TOPO_VERTEX"."NODE_Y" IS 'Y的坐标位置';
   COMMENT ON COLUMN "TOPO_VERTEX"."NODE_WIDTH" IS '节点的宽度';
   COMMENT ON COLUMN "TOPO_VERTEX"."NODE_HEIGHT" IS '节点的高度';
   COMMENT ON COLUMN "TOPO_VERTEX"."NODE_CONNECTABLE" IS '是否允许连接（0:不允许，1：允许）';
   COMMENT ON COLUMN "TOPO_VERTEX"."ORG_ID" IS '组织结构ID';
   COMMENT ON COLUMN "TOPO_VERTEX"."ASSET_ID" IS '设备ID或者机柜ID';
   COMMENT ON COLUMN "TOPO_VERTEX"."OFFSET_X" IS 'x偏移量';
   COMMENT ON COLUMN "TOPO_VERTEX"."OFFSET_Y" IS 'y偏移量';
   COMMENT ON COLUMN "TOPO_VERTEX"."IS_PORT" IS '是否为端口节点';
   COMMENT ON COLUMN "TOPO_VERTEX"."PORT_INDEX" IS '端口索引号';
   COMMENT ON TABLE "TOPO_VERTEX"  IS '网络拓扑节点位置表';
