Insert into PERFORMANCE_TARGET (ID,ASSET_MODE,SPEC_ID,IS_AVAILABLE,TARGET_HANDLE,TARGET_DESCRIPTION,CRON_EXPRESS,COMMAND,COMMAND_NAME) values ('30',183,5,1,'SERVER_AIX_TIME','AIX系统时间采集','0 0/1 * * * ? *','date +"%Y-%m-%d %H:%M:%S"','系统时间采集');
Insert into PERFORMANCE_TARGET (ID,ASSET_MODE,SPEC_ID,IS_AVAILABLE,TARGET_HANDLE,TARGET_DESCRIPTION,CRON_EXPRESS,COMMAND,COMMAND_NAME) values ('27',263,4,1,'ORACLE_DB','ORACLE数据库采集','0 0/1 * * * ? *','select to_char(round((sysdate - startup_time)*24*60*60*1000,0)) "sysUpTime" from v$instance|select status "status" from v$instance|select version "dbVersion"  from v$INSTANCE|select count(*) "dbSessionSize" from v$session|select count(*) "dbConnection" from v$process|select count(*) "dbActive" from v$session where status=''ACTIVE''|select round(100 - (phy.value - (direct.value + lob.value))/(consis.value + block.value - (direct.value + lob.value))*100, 2)  "dbCachePoolhit" from v$sysstat phy, v$sysstat direct, v$sysstat lob, v$sysstat consis, v$sysstat block where phy.name = ''physical reads'' and direct.name = ''physical reads direct'' and lob.name = ''physical reads direct (lob)'' and consis.name = ''consistent gets'' and block.name = ''db block gets''|select round(sum(pinhits-reloads)/sum(pins)*100, 2) "cacheLibrary" from v$librarycache|select count(*) "canUseLockSize" from v$latch|select round(100 - 100 * (sum(MISSES)/sum(GETS)), 2) "dbLockUsedRate" from v$latch|select round((100 * (sum(MISSES)/sum(GETS))), 0) as "dbLockWaitRate" from  v$latch|select round(100 *((select count(*) from v$session)/(select value from v$parameter where name = ''sessions'')), 2) "dbSessionUsedRate" from dual|select round(sum(bytes)/1024/1024, 2) as "dbCachePoolSize" from v$sgastat where pool = ''shared pool'' group by pool|select bytes/1024/1024 "javaPoolSize" from v$sgainfo where name = ''Java Pool Size''|select bytes/1024/1024 "largePoolSize" from v$sgainfo where name = ''Large Pool Size''|select round(bytes/1024/1024, 2) "redoLogBuffer" from v$sgastat where name =''log_buffer''|SELECT VALUE/(1024*1024) as "dbCache" FROM V$SGA WHERE NAME = ''Database Buffers''|select round(value/1024/1024/1024, 2) "dbMemTotal" from v$osstat where stat_name =''PHYSICAL_MEMORY_BYTES''|select round(a.value * 100/(a.value + b.value), 2) "dbBusynessRate" from v$sysstat a, v$sysstat b where a.name = ''buffer is pinned count'' and b.name = ''buffer is not pinned count''|select a.tablespace_name "name", round(b.total/1024/1024, 0) "totalSize", round(a.free/1024/1024, 0) "freeSize", round((b.total - a.free)/1024/1024, 0) "usedSize", to_char((b.total - a.free)*100/b.total, ''90.99'') "usedRate" from (select tablespace_name,sum(BYTES) free from  dba_free_space group by tablespace_name) a, (select tablespace_name, sum(BYTES) total from dba_data_files group by tablespace_name) b where a.tablespace_name = b.tablespace_name','sysUpTime|status|dbVersion|dbSessionSize|dbConnection|dbActive|dbCachePoolhit|cacheLibrary|canUseLockSize|dbLockUsedRate|dbLockWaitRate|dbSessionUsedRate|dbCachePoolSize|javaPoolSize|largePoolSize|redoLogBuffer|dbCache|dbMemTotal|dbBusynessRate|tableSpace');
