Insert into ALARM_REPOSITORY (ID,NAME,ALARM_LEVEL,ALARM_CODE,MANUFACTURER_ID,ASSET_MODE,DESC_STR,PLAN_STR,STATUS,CREATE_TIME,CREATOR,MODIFY_TIME,MODIFIER) values ('1300271467161579520','一个指向访问列表的指针是无效的',2,'%SYS-2-BADLIST',4,1,'这个消息表明一个指向访问列表的指针是无效的。','导致发出此消息的事件不应该发生。它可能意味着已经覆盖了一个或多个数据结构。你决定把它报告给你的技术代表，你应该准确地复制消息的文本，包括相关的堆栈跟踪。由于访问列表损坏可能已经发生，技术代表应该验证访问列表是否正常运行。',1,to_date('2020-08-31 11:17:37','YYYY-MM-DD HH24:MI:SS'),'系统',to_date('2020-08-31 11:17:37','YYYY-MM-DD HH24:MI:SS'),'系统');
