Insert into ALARM_REPOSITORY (ID,NAME,ALARM_LEVEL,ALARM_CODE,MANUFACTURER_ID,ASSET_MODE,DESC_STR,PLAN_STR,STATUS,CREATE_TIME,CREATOR,MODIFY_TIME,MODIFIER) values ('1300271467302199297','传感器[SensorElementName]已从不太严重状态转换至紧急状态。（PS1散热故障）',1,'800702080a01ffff',1,1,'实施过程检测到“传感器已从不太严重状态变为紧急状态”。','1.确保没有障碍物（如成束的线缆）阻挡电源模块风扇的气流。2.使用LenovoPowerConfigurator实用程序确保当前系统耗电量不超限。若要获取更多信息和下载该实用程序，请访问https://www.ibm.com/support/entry/myportal/docdisplay?lndocid=LNVO-PWRCONF。3.更换电源模块n。（n=电源模块编号）',1,to_date('2020-08-31 11:17:41','YYYY-MM-DD HH24:MI:SS'),'系统',to_date('2020-08-31 11:17:41','YYYY-MM-DD HH24:MI:SS'),'系统');
